"use strict";
// ES2015 proper tail calls: constant stack on JavaScriptCore, RangeError elsewhere
function sumTo(n, acc = 0) {
  if (n === 0) return acc;
  return sumTo(n - 1, acc + n);   // tail position, spec-mandated elimination
}

